    if isinstance(v, CommandOffer):
        m["decision"] = encode_decision(v.decision)
    if isinstance(v, CommandApply):
        m["decision"] = enc_string(v.decision)
        m["choice"] = enc_string(v.choice)
    if isinstance(v, CommandAck):
        m["of"] = enc_string(v.of)
        m["status"] = encode_command_status(v.status)
        if v.detail is not None:
            m["detail"] = enc_string(v.detail)
    if isinstance(v, CommandSettle):
        m["decision"] = enc_string(v.decision)
        m["choice"] = enc_string(v.choice)
        m["phase"] = encode_phase(v.phase)
        if v.accesses is not None:
            m["accesses"] = [encode_footprint(e) for e in v.accesses]
        if v.detail is not None:
            m["detail"] = enc_string(v.detail)
