# Evidence a rule's meaning requires. Missing required evidence makes a result unknown, never a pass.
EVIDENCE_NEED_VALUES = ("baseline_state", "final_state", "statement_history", "transaction_outcomes", "settled_trial", "effect_receipts")


def encode_evidence_need(v: str):
    return enc_string(v)


def decode_evidence_need(j, path: str) -> str:
    return dec_enum(j, path, EVIDENCE_NEED_VALUES, "EvidenceNeed")


@dataclass
class RuleMeaning:
    """The part of a rule that defines what it means. Its canonical digest is the rule's semantics digest; ids, intent level and provenance are not meaning."""

    body: "RuleBody"
    unless: list["Condition"]
    units: dict[str, str]
    evidence: list["EvidenceNeed"]


def encode_rule_meaning(v: RuleMeaning):
    m = {}
    m["body"] = encode_rule_body(v.body)
    m["unless"] = [encode_condition(e) for e in v.unless]
    m["units"] = {k: enc_string(e) for k, e in v.units.items()}
    m["evidence"] = [encode_evidence_need(e) for e in v.evidence]
    return m


