@dataclass
class RuleVersion:
    """An immutable typed rule: meaning, its semantics digest (sha256 of the meaning's canonical bytes), intent level and provenance. Rows/effects matching any unless condition are exempt. A digest that does not match the meaning is refused."""

    id: str
    meaning: "RuleMeaning"
    digest: str
    intent: "IntentLevel"
    provenance: str


