    return SuiteSignatureInput(record_type=req(m, "record_type", path, dec_id), record=req(m, "record", path, dec_digest), profile=req(m, "profile", path, dec_id), suite=req(m, "suite", path, dec_id), algorithm=req(m, "algorithm", path, dec_id), key=req(m, "key", path, dec_id))


