# Whether a variation can run for this agent. unsupported always states why and runs nothing; it is never replaced by a weaker simulation.
@dataclass
class PerturbationSupportSupported:
    KIND: ClassVar[str] = "supported"


@dataclass
class PerturbationSupportUnsupported:
    KIND: ClassVar[str] = "unsupported"
    reason: str


PerturbationSupport = Union[PerturbationSupportSupported, PerturbationSupportUnsupported]


def encode_perturbation_support(v):
    m = {"kind": v.KIND}
    if isinstance(v, PerturbationSupportSupported):
        pass
    if isinstance(v, PerturbationSupportUnsupported):
        m["reason"] = enc_string(v.reason)
    return m


def decode_perturbation_support(j, path: str):
    m = obj(j, path)
    kind = req(m, "kind", path, dec_string)
    if kind == "supported":
        only_fields(m, ("kind",), path)
        return PerturbationSupportSupported()
    if kind == "unsupported":
        only_fields(m, ("reason", "kind"), path)
        return PerturbationSupportUnsupported(reason=req(m, "reason", path, dec_string))
    raise DecodeError("unknown_variant", path, f"unknown PerturbationSupport {kind}")


